#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_completion;
uniform float amzp_style;
uniform float amzp_cols;
uniform float amzp_square;
uniform float amzp_rows;
uniform float amzp_wAngle;
uniform float amzp_alt;
uniform float amzp_delay;
uniform float amzp_order;
uniform float amzp_oAngle;
uniform float amzp_stagger;
uniform float amzp_soft;
uniform float amzp_seed;
uniform float amzp_advScale;
uniform float amzp_advAngle;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.5) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float hh(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 3.17) * 43758.5453); }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 src = (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) ? float4(0.0) : amzTexture(0, l2s(uv));
        float C = clamp(prog(amzp_completion), 0.0, 1.0);
        if (C <= 0.0) { amzOutput = src; return; }
        if (C >= 1.0) { amzOutput = float4(0.0); return; }
        float S = max(amzp_advScale, 0.01);
        float2 g = advRot((uv - 0.5) * W, radians(amzp_advAngle)) / S + W * 0.5;
        float nc = max(floor(amzp_cols + 0.5), 1.0);
        float cw = W.x / nc;
        float nr = (amzp_square>0.5) ? max(floor(W.y / cw + 0.5), 1.0) : max(floor(amzp_rows + 0.5), 1.0);
        float2 cs = float2(cw, W.y / nr);
        float2 cell = floor(g / cs);
        float2 lc = (g - (cell + 0.5) * cs);
        float par = mod(cell.x + cell.y, 2.0);
        float2 nrm = (cell + 0.5) / float2(nc, nr);
        float o = 0.0;
        if (int(amzp_order) == 1) {
            float a = radians(amzp_oAngle);
            float2 d = float2(sin(a), cos(a));
            o = dot(nrm - 0.5, d) / (0.5 * (abs(d.x) + abs(d.y))) * 0.5 + 0.5;
        } else if (int(amzp_order) == 2) {
            o = length((nrm - 0.5) * W) / length(W * 0.5);
        } else if (int(amzp_order) == 3) {
            o = hh(cell);
        }
        float stg = int(amzp_order) == 0 ? 0.0 : max(amzp_stagger, 0.0);
        float dl = max(amzp_delay, 0.0);
        float total = 1.0 + dl + stg;
        float lp = clamp(C * total - par * dl - o * stg, 0.0, 1.0);
        float sf = max(amzp_soft, 0.0) + 0.5;
        float vis;
        float2 hs = cs * 0.5;
        if (int(amzp_style) == 0) {
            float a = radians(amzp_wAngle) + (((amzp_alt>0.5) && par > 0.5) ? 3.14159265 : 0.0);
            float2 d = float2(cos(a), sin(a));
            float ext = abs(hs.x * d.x) + abs(hs.y * d.y);
            float e = dot(lc, d);
            vis = smoothstep(-sf, sf, e - (lp * 2.0 - 1.0) * (ext + sf));
        } else if (int(amzp_style) == 1 || int(amzp_style) == 2) {
            float2 q = lc;
            if (int(amzp_style) == 2) q = advRot(q, lp * 3.14159265 * 0.5 * (((amzp_alt>0.5) && par > 0.5) ? -1.0 : 1.0));
            float2 lim = hs * (1.0 - lp);
            float2 dd = lim - abs(q);
            vis = smoothstep(-sf, sf, min(dd.x, dd.y)) * step(0.0001, 1.0 - lp);
        } else if (int(amzp_style) == 3) {
            vis = 1.0 - lp;
        } else if (int(amzp_style) == 4) {
            float R = length(hs) * (1.0 - lp);
            vis = smoothstep(-sf, sf, R - length(lc)) * step(0.0001, 1.0 - lp);
        } else {
            bool hor = ((amzp_alt>0.5) && par > 0.5);
            float e = hor ? abs(lc.y) / hs.y : abs(lc.x) / hs.x;
            vis = smoothstep(-sf / hs.x, sf / hs.x, e - lp);
        }
        amzOutput = src * clamp(vis, 0.0, 1.0);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
